import{currentUserRole}from"@/lib/role";import{redirect}from"next/navigation";import Link from"next/link";export default async function Earnings(){const{user,role,s}=await currentUserRole();if(!user)redirect("/auth");if(role!=="vendor")redirect(role==="admin"?"/admin":"/");const{data:o}=await s.from("orders").select("gas_amount_kobo").eq("vendor_user_id",user.id).eq("status","delivered");const gross=(o||[]).reduce((n,x)=>n+Number(x.gas_amount_kobo),0);return <main className="shell"><h1>Earnings</h1><section className="card"><span className="muted">Delivered gas value</span><div className="price">₦{(gross/100).toLocaleString()}</div></section><p className="muted">This is delivered gas value, not a settlement balance. Vendor payouts will be added with the payment provider.</p><Link className="btn" href="/vendor">Back to dashboard</Link></main>}